pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner;
    address spender;
    uint256 value;

    function setUp() public {
        c = new C(0, bytes16(0), address(this), address(this), address(this));
        owner = address(0x1234);
        spender = address(0x5678);
        value = 100;
    }

    function testFuzz_property(address _spender, uint256 _value) public {
        // Bound inputs to reasonable ranges
        vm.assume(_spender != address(0));
        vm.assume(_value > 0 && _value < 1e30);

        // Record the wards state before the call
        uint256 wardsBefore = c.wards(address(this));

        // Call allowance, which goes through the share token's transferFrom (via delegatecall)
        // The call doesn't revert; it just returns a boolean
        c.allowance(owner, _spender);

        // After the call, the auth status of address(this) must still be 1
        // In the reference contract, the modifier requires wards[msg.sender] == 1, so only authorized callers pass.
        // The allowance call itself doesn't change wards, so address(this) remains authorized.
        // In the mutant, the modifier requires wards[msg.sender] == 0, so only unauthorized callers pass.
        // But address(this) is authorized (==1), so the mutant's allowance call will revert.
        uint256 wardsAfter = c.wards(address(this));
        assertTrue(wardsAfter == 1, "Authorization should persist");
    }
}

